INSERT INTO `cpl` (`id`, `kodeCpl`, `deskripsi`, `nilaiMinimal`, `targetPersen`, `created_at`, `updated_at`) VALUES
(1, 'CPL-01', 'Kemampuan menerapkan pengetahuan matematika, ilmu pengetahuan  alam dan/atau material, teknologi informasi dan keteknikan untuk menyelesaikan permasalahan dalam bidang teknik pertanian dan biosistem.', 60, 60, '2025-07-13 13:31:49', '2025-07-13 13:31:49'),
(2, 'CPL-02', 'Kemampuan mendesain komponen, sistem dan/atau proses untuk memenuhi kebutuhan yang diharapkan didalam batasan-batasan realistis, misalnya hukum, ekonomi, lingkungan, sosial, politik, kesehatan dan keselamatan, keberlanjutan pertanian serta untuk mengenali dan/atau memanfaatkan potensi sumber daya lokal dan nasional dengan wawasan global', 60, 60, '2025-07-13 13:32:04', '2025-07-13 13:32:04'),
(5, 'CPL-03', 'Kemampuan mendesain dan melaksanakan eksperimen laboratorium dan/atau lapangan serta menganalisis dan mengartikan data untuk memperkuat penilaian teknik pertanian dan biosistem', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14'),
(6, 'CPL-04', 'Kemampuan menganalisis dan menyelesaikan permasalahan teknik pertanian dan biosistem', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14'),
(7, 'CPL-05', 'Kemampuan menerapkan metode, keterampilan dan piranti teknik yang modern yang diperlukan untuk praktek keteknikan pertanian dan biosistem', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14'),
(8, 'CPL-06', 'Kemampuan berkomunikasi secara efektif baik lisan maupun  tulisan', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14'),
(9, 'CPL-07', 'Kemampuan merencanakan, menyelesaikan dan mengevaluasi tugas di dalam batasan-batasan yang ada.', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14'),
(10, 'CPL-08', 'Kemampuan untuk mendemonstrasikan bekerja dalam tim lintas disiplin dan lintas budaya', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14'),
(11, 'CPL-09', 'Kemampuan  untuk bertanggung jawab kepada masyarakat dan mematuhi etika profesi dalam menyelesaikan permasalahan teknik pertanian dan biosistem', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14'),
(12, 'CPL-10', 'Kemampuan menerapkan akan kebutuhan pembelajaran sepanjang hayat, termasuk akses terhadap pengetahuan terkait isu-isu terkini yang relevan', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14'),
(13, 'CPL-11', 'Mampu mengaplikasikan prinsip kewirausahaan untuk dapat berkontribusi pada pembangunan', 60, 60, '2025-07-17 13:40:14', '2025-07-17 13:40:14');
