(631, 'CPMK-1', '1.	Mahasiswa mampu menjelaskan secara logis  dan sistematis mengenai teori dan persfektif kewirausahaan  (CP-7,PI 7.1)', '2026-09-06 12:47:09', '2026-09-06 12:47:09'),
(632, 'CPMK-2', '2.	Mampu menjelaskan  dan menggambarkan peluang, tantangan  dan tahapan dalam menciptakan konsep kewirausahaan (CP-11, PI 11.1)', '2026-09-06 12:48:15', '2026-09-06 12:48:15'),
(633, 'CPMK-3', 'Mahasiswa mampu  menjelaskan karakter individu yang positif dan memiliki motivasi yang tinggi  dalam berwirausaha (CP-11, P11.2)', '2026-09-06 12:49:12', '2026-09-06 12:49:12'),
(634, 'CPMK-4', '4.	Mahasiswa mampu menjelaskan dan memecahkan studi kasus terkait faktor sukses dan gagalnya  dalam berwirausaha (CP-7, PI 7.1)', '2026-09-06 12:50:00', '2026-09-06 12:50:00'),
(635, 'CPMK-5', 'Mahasiswa memiliki kemampuan  inovasi dan pengembangan ide usaha (CP11,,PI 11.4)', '2026-09-06 12:50:33', '2026-09-06 12:50:33'),
(636, 'CPMK-6', 'Mahasiswa  mampu mengimplementasikan konsep kewirausahaan    kedalam sebuah bisnis rintisan atau starup (CP11,PI 11.3)', '2026-09-06 12:51:09', '2026-09-06 12:51:09'),
(637, 'CPMK-1', 'Mahasiswa memiliki pemahaman tentang azas dasar mekanika mesin, mesin sederhana dan gesekan', '2026-09-06 23:04:23', '2026-09-06 23:04:23'),
(638, 'CPMK-2', 'Mahasiswa mampu menganalisis tegangan satu dan dua dimensi, perencanaan pada poros, serta perhitungan mekanika pada komponen mesin', '2026-09-06 23:04:53', '2026-09-06 23:04:53'),
